create table if not exists public.capability_feature_contracts (id uuid primary key default gen_random_uuid(), feature_code text not null references public.feature_catalog(feature_code) on update cascade, canonical_capability text not null, mapping_type text not null default 'primary', evidence_status text not null default 'unverified', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(feature_code,canonical_capability), check (mapping_type in ('primary','secondary','supporting')), check (evidence_status in ('verified','unverified','orphaned','blocked')));
create index if not exists idx_capability_feature_contracts_capability on public.capability_feature_contracts(canonical_capability);
create index if not exists idx_capability_feature_contracts_feature on public.capability_feature_contracts(feature_code);
revoke all on public.capability_feature_contracts from public;
revoke all on public.capability_feature_contracts from anon;
revoke all on public.capability_feature_contracts from authenticated;
create or replace function public.admin_operational_capability_catalog() returns jsonb language plpgsql security definer set search_path=public as $$
declare v_result jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required'; end if;
 if not public.is_platform_owner(auth.uid()) then raise exception 'admin authorization required'; end if;
 with caps as (select c.*, exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=c.canonical_rpc) rpc_exists, exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=c.canonical_rpc and has_function_privilege('authenticated',p.oid,'EXECUTE')) auth_execute, exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=c.canonical_rpc and has_function_privilege('anon',p.oid,'EXECUTE')) anon_execute, (select count(*) from capability_feature_contracts m where m.canonical_capability=c.canonical_capability) feature_mappings from capability_domain_contracts c where c.active), feature_summary as (select count(*) total, count(*) filter(where m.id is null) orphaned from feature_catalog f left join capability_feature_contracts m on m.feature_code=f.feature_code and m.evidence_status <> 'orphaned' where f.enabled), statuses as (select *,case when not rpc_exists then 'missing_rpc' when not auth_execute or anon_execute then 'authorization_gap' when feature_mappings=0 then 'unmapped_feature' else 'unverified' end status from caps) select jsonb_build_object('generated_at',now(),'source','live_contract_feature_authorization','summary',jsonb_build_object('capabilities',count(*),'backend_contract_present',count(*) filter(where rpc_exists and auth_execute and not anon_execute),'wired',count(*) filter(where status='wired'),'not_wired',count(*) filter(where status<>'wired'),'unverified',count(*) filter(where status='unverified'),'missing_rpc',count(*) filter(where status='missing_rpc'),'authorization_gap',count(*) filter(where status='authorization_gap'),'unmapped_feature',count(*) filter(where status='unmapped_feature'),'features', (select total from feature_summary),'orphaned_features',(select orphaned from feature_summary)),'items',coalesce(jsonb_agg(jsonb_build_object('domain',domain,'capability',canonical_capability,'rpc',canonical_rpc,'surface',owner_surface,'status',status,'feature_mappings',feature_mappings,'rpc_exists',rpc_exists,'authenticated_execute',auth_execute,'anon_execute',anon_execute) order by domain),'[]'::jsonb)) into v_result from statuses; return v_result; end; $$;
